    for run in ImportRun.objects.filter(owner__isnull=True):
        owner_ids = set(
            run.transactions.exclude(owner__isnull=True).values_list(
                "owner_id", flat=True
            )
        )
        if len(owner_ids) == 1:
            run.owner_id = owner_ids.pop()
            run.save(update_fields=["owner"])


